/* Proactive checks and local escalation simulation. No remote dispatch. */
state.escalations??=[];state.safetyNotes??={};state.alertSettings??={physicianPhone:'',icuPhone:'',ackMinutes:2};
navs.push('Escalation center');
function safetyIssues(p){const pid=id(p),a=assess(p),c=careFor(pid),issues=[],add=(key,severity,title,action,tab)=>issues.push({key:pid+'-'+key,patientId:pid,severity,title,action,tab});if(typeof p['Systolic BP (mmHg)']==='number'&&p['Systolic BP (mmHg)']<90)add('bp','urgent','Recorded hypotension: prompt clinical review','Review current condition; confirm measurement and time. Baseline may be historical.','Summary');if(a.risk==='Unknown')add('missing','review','Incomplete risk assessment','Complete missing assessment fields; do not assume low risk.','Summary');if(state.allergies[pid]?.status!=='none'&&state.allergies[pid]?.status!=='known')add('allergy','review','Allergy status not documented','Verify allergy history before medication review.','Summary');if(c.steps.dose?.status==='done'&&!c.treatment?.administeredAt)add('dose','review','Administration checklist has no matching treatment time','Reconcile actual administration documentation.','Care checklist');if(c.disposition?.status==='Discharged (synthetic)'&&!c.followup?.dueAt)add('followup','review','Discharge record has no scheduled follow-up time','Record follow-up and safety-net plan.','Treatment & disposition');if(c.disposition?.status==='Discharged (synthetic)'&&a.risk!=='Low')add('risk-discharge','urgent','Discharge history conflicts with current risk','Review changed assessment and disposition; no automatic discharge authorization.','Treatment & disposition');for(const r of labAlerts(pid).filter(r=>!state.labReviews[r.eventId]))add('result-'+r.eventId,r.critical?'urgent':'review','Unreviewed '+r.code+' result','Open the result and document review; acknowledgment is not resolution.',r.code==='culture'?'Cultures':'Laboratory');return issues}
function allSafetyIssues(){return patients.flatMap(safetyIssues)}
const oldSafetyPage=safety;safety=function(){const issues=allSafetyIssues(),urgent=issues.filter(i=>i.severity==='urgent'),review=issues.filter(i=>i.severity==='review');return header('Proactive safety','Find care gaps before completing the next step.',`<button class="btn primary" onclick="go('Escalation center')">Escalation center →</button>`)+`<div class="banner">Draft prototype checks · derived from current local records, including historical baseline values. Verify freshness and clinical context before action.</div><div class="compactstats"><span><b>${urgent.length}</b> urgent review flags</span><span><b>${review.length}</b> documentation / review gaps</span><span><b>${state.escalations.filter(e=>e.status!=='closed').length}</b> open demo escalations</span></div><div class="grid2"><section class="panel"><h2>Priority review queue</h2><p>Highest-priority flags shown first; repeated same-patient issues stay linked to that case.</p>${[...urgent,...review].slice(0,15).map(i=>`<div class="safetyissue"><span class="pill ${i.severity==='urgent'?'red':'amber'}">${i.severity==='urgent'?'Urgent review':'Proactive check'}</span><h3>${esc(i.title)}</h3><p>${esc(patientName(patients.find(p=>id(p)===i.patientId)))} · ${esc(i.patientId)}</p><p>${esc(i.action)}</p><div class="actions"><button class="btn" onclick="openPatient('${i.patientId}');changeTab('${i.tab}')">Inspect & act →</button>${i.severity==='urgent'?`<button class="btn" onclick="openEscalation('${i.patientId}')">Escalate demo</button>`:''}</div></div>`).join('')||'<p>No detected gaps in available records. This does not establish absence of clinical risk.</p>'}<p>Showing up to 15 of ${issues.length}. Open a patient for its full context.</p></section><section class="panel"><h2>Failure prevention rules</h2><button class="btn" onclick="toggleSafetyMonitor()">${state.localSafetyMonitor?'Disable':'Enable'} in-app safety monitoring</button><p>Detect new urgent flags while this app is open; no background or remote dispatch.</p><div class="stage">Missing data → explicit Unknown state</div><div class="stage">Source-critical result → hard gate on demo review completion</div><div class="stage">Other review gaps → soft stop with documented deferral</div><div class="stage">New risk vs old discharge → conflict flagged</div><div class="stage">Checklist vs administration record → reconciliation</div><div class="stage">Escalation without response → overdue status, not false delivery</div><h3>Human factors</h3><p>Visibility, workflow fit, consistency, low cognitive load, error prevention and clear feedback. Notifications use a minimal message; case details stay inside the application.</p><button class="btn" onclick="showProcessReference()">FMEA, process & usability reference</button><button class="btn" style="margin-top:10px" onclick="showSafetyFeedback()">Review feedback</button></section></div>`};
function showProcessReference(){openDialog('Process & FMEA reference',oldSafetyPage());document.querySelector('#workflowDialog').classList.add('assessmentdialog')}
function openEscalation(pid){const p=patients.find(p=>id(p)===pid);if(!p)return;openDialog('Create demo escalation · '+esc(patientName(p)),`<p>Simulation only. No physician, ICU, watch or corridor hardware receives this request. Confirm current clinical context independently.</p><form onsubmit="event.preventDefault();createEscalation('${pid}',this)"><label class="field">Trigger / assessment note<textarea name="reason" required maxlength="600" placeholder="Record the observed concern, measurement time and requested response"></textarea></label><label class="field">Route<select name="target"><option>Physician first</option><option>Physician + ICU assessment</option></select></label><label class="field">Demo acknowledgment window (minutes)<input name="minutes" type="number" min="1" max="60" value="${state.alertSettings.ackMinutes}" required></label><p>This configurable demo interval is not an approved emergency-response standard.</p><div class="actions"><button class="btn primary" type="submit">Create local escalation</button><button class="btn" type="button" onclick="closeDialog()">Cancel</button></div></form>`)}
function createEscalation(pid,form){const f=new FormData(form),reason=String(f.get('reason')||'').trim(),minutes=Number(f.get('minutes'));if(!reason||!Number.isFinite(minutes)||minutes<1||minutes>60)return;const existing=state.escalations.find(e=>e.patientId===pid&&e.status!=='closed');if(existing){closeDialog();go('Escalation center');return}const now=Date.now(),e={id:'ESC-'+now+'-'+state.escalations.length,patientId:pid,reason,target:String(f.get('target')),createdAt:new Date(now).toISOString(),dueAt:new Date(now+minutes*60000).toISOString(),status:'awaiting-demo-ack',events:[{time:new Date(now).toISOString(),action:'Local simulation created; no external dispatch'}]};state.escalations.unshift(e);closeDialog();view='Escalation center';save('Created local escalation '+e.id+'; no external notification',pid)}
function escalationStatus(e,now=Date.now()){if(e.status==='closed')return 'Closed';if(e.status==='acknowledged')return 'Acknowledged (demo)';if(Date.parse(e.dueAt)<now)return 'Overdue · no demo response';return 'Awaiting demo acknowledgment'}
function escalationView(){return header('Escalation center','Visible ownership, response tracking and honest channel status.',`<button class="btn" onclick="configureChannels()">Channels & test notification</button>`)+`<div class="notice"><b>SIMULATION — not an emergency dispatch service.</b> No remote physician / ICU delivery, automatic call, watch delivery or corridor light is connected. Do not use for real emergencies.</div><div class="grid2"><section class="panel"><h2>Open a case escalation</h2><label class="field">Select synthetic patient<select id="escalationPatient">${patients.map(p=>`<option value="${esc(id(p))}" ${selected&&id(selected)===id(p)?'selected':''}>${esc(patientLabel(p))}</option>`).join('')}</select></label><button class="btn primary" onclick="openEscalation(document.querySelector('#escalationPatient').value)">Create escalation →</button><div class="actions"><button class="btn" onclick="testLocalNotification()">Test notification on this device</button><button class="btn" onclick="previewLight()">Preview red light</button></div></section><section class="panel"><h2>Channel readiness</h2><div class="stage">In-app queue: functional on this device</div><div class="stage">Local OS notification: ${typeof Notification==='undefined'?'unsupported / unavailable':esc(Notification.permission)} · user-initiated test only</div><div class="stage">Phone dialer: ${state.alertSettings.physicianPhone?'number configured':'not configured'} · manual opening only</div><div class="stage">Remote push / watch / automated voice: not connected</div><div class="stage">Corridor beacon / nurse-call gateway: not connected</div><button class="btn" onclick="downloadEscalationContract()">Export proposed integration contract</button></section></div><section class="panel" style="margin-top:20px"><h2>Escalation queue</h2>${state.escalations.map(e=>`<div class="escalationcard"><span class="pill ${escalationStatus(e).startsWith('Overdue')?'red':'amber'}">${esc(escalationStatus(e))}</span><h3>${esc(e.id)} · ${esc(e.patientId)}</h3><p>${esc(e.reason)}</p><p>Route: ${esc(e.target)} · created ${fmt(e.createdAt)} · due ${fmt(e.dueAt)}</p><div class="actions"><button class="btn" onclick="openPatient('${e.patientId}')">Open case</button>${e.status!=='closed'?`<button class="btn" onclick="updateEscalation('${e.id}','ack')">Simulate physician acknowledgment</button><button class="btn" onclick="updateEscalation('${e.id}','icu')">Simulate ICU escalation</button><button class="btn" onclick="closeEscalation('${e.id}')">Close with outcome</button>`:''}<button class="btn" onclick="showEscalationHistory('${e.id}')">Event history</button></div><p class="mini">Simulation actions do not prove real delivery or a clinician response.</p></div>`).join('')||'<div class="empty">No escalations yet. Select a case above to test the workflow.</div>'}</section>`}
function updateEscalation(eid,action){const e=state.escalations.find(e=>e.id===eid);if(!e||e.status==='closed')return;const time=new Date().toISOString();if(action==='ack')e.status='acknowledged';if(action==='icu')e.target='Physician + ICU assessment (simulated)';e.events.push({time,action:action==='ack'?'Physician acknowledgment simulated':'ICU escalation simulated; no message sent'});save(e.events.at(-1).action+'; '+eid,e.patientId)}
function closeEscalation(eid){const e=state.escalations.find(e=>e.id===eid);if(!e)return;openDialog('Close demo escalation',`<form onsubmit="event.preventDefault();saveEscalationOutcome('${eid}',this)"><label class="field">Outcome / reflection<textarea name="outcome" required maxlength="600"></textarea></label><button class="btn primary" type="submit">Save outcome</button><button class="btn" type="button" onclick="closeDialog()">Back</button></form>`)}
function saveEscalationOutcome(eid,form){const e=state.escalations.find(e=>e.id===eid),outcome=String(new FormData(form).get('outcome')||'').trim();if(!e||!outcome)return;e.status='closed';e.outcome=outcome;e.closedAt=new Date().toISOString();e.events.push({time:e.closedAt,action:'Closed demo escalation: '+outcome});closeDialog();save('Closed local escalation '+eid+'; '+outcome,e.patientId)}
function showEscalationHistory(eid){const e=state.escalations.find(e=>e.id===eid);if(!e)return;openDialog('Escalation history',e.events.map(x=>`<div class="stage"><b>${esc(fmt(x.time))}</b><p>${esc(x.action)}</p></div>`).join(''))}
function configureChannels(){openDialog('Channels & notification test',`<p>Manual dialer numbers are stored on this device. No service credentials are collected. Remote channels require an authenticated backend and hospital approval.</p><form onsubmit="event.preventDefault();saveChannelSettings(this)"><label class="field">Physician phone (optional)<input type="tel" name="physicianPhone" value="${esc(state.alertSettings.physicianPhone)}" placeholder="Enter an authorized test number"></label><label class="field">ICU phone (optional)<input type="tel" name="icuPhone" value="${esc(state.alertSettings.icuPhone)}"></label><label class="field">Demo acknowledgment window (minutes)<input type="number" min="1" max="60" name="ackMinutes" value="${state.alertSettings.ackMinutes}" required></label><button class="btn primary" type="submit">Save local settings</button></form><div class="actions"><button class="btn" onclick="testLocalNotification()">Request permission & test on this device</button><button class="btn" onclick="openDialer('physicianPhone')">Open physician dialer</button><button class="btn" onclick="openDialer('icuPhone')">Open ICU dialer</button></div><p id="channelMessage" role="status"></p><details><summary>Real implementation requirements</summary><p>Server-side dispatch queue, authenticated on-call roster, approved push/voice provider, delivery receipts, clinician acknowledgment, backup routes and monitored escalation timers. A watch requires supported notification routing or a clinical native integration. A corridor beacon requires an approved nurse-call / IoT gateway and hardware acknowledgment. No guaranteed delivery follows from a browser notification.</p></details>`)}
function saveChannelSettings(form){const f=new FormData(form),phone=k=>String(f.get(k)||'').trim();for(const k of ['physicianPhone','icuPhone'])if(phone(k)&&!/^\+?[0-9 ()-]{5,25}$/.test(phone(k))){channelMessage('Use a valid test phone number.');return}const mins=Number(f.get('ackMinutes'));if(!Number.isFinite(mins)||mins<1||mins>60)return;state.alertSettings={physicianPhone:phone('physicianPhone'),icuPhone:phone('icuPhone'),ackMinutes:mins};closeDialog();save('Updated local test channel settings; no connection established')}
function channelMessage(s){const el=document.querySelector('#channelMessage');if(el)el.textContent=s;else openDialog('Notification test',`<p>${esc(s)}</p><button class="btn" onclick="closeDialog()">Close</button>`)}
async function testLocalNotification(){try{if(typeof Notification==='undefined'||!window.isSecureContext){channelMessage('System notifications are not available in this browser context. In-app alerts still work.');return}const permission=await Notification.requestPermission();if(permission!=='granted'){channelMessage('Notification permission was not granted. No system notification sent.');return}const reg=await navigator.serviceWorker.getRegistration();if(reg)await reg.showNotification('FN Clinical · TEST ONLY',{body:'Synthetic workflow test. Open the app to review. No clinical dispatch.',tag:'fn-local-test',icon:'icon-192.png'});else new Notification('FN Clinical · TEST ONLY',{body:'Local test only; no remote clinician notified.'});save('Requested local OS test notification; remote/watch delivery not verified');channelMessage('Test notification requested on this device. OS display and watch forwarding are not verified; remote/background push is not connected.')}catch(e){channelMessage('Notification test failed: '+e.message)}}
function openDialer(key){const number=state.alertSettings[key];if(!number){channelMessage('Save an authorized test phone number first.');return}save('Manual dialer requested; no call connection verified');window.location.href='tel:'+number.replace(/[^+0-9]/g,'')}
function previewLight(){openDialog('Corridor beacon · visual simulation',`<div class="beaconpreview"><div class="beaconlamp"></div><b>RED LIGHT PREVIEW</b><p>Screen simulation only. No corridor light or nurse-call hardware is connected.</p></div><button class="btn" onclick="closeDialog()">Stop preview</button>`)}
function downloadEscalationContract(){download('fn-escalation-contract.json',{status:'PROPOSED_NOT_CONNECTED',privacy:'Use synthetic patient identifiers only in tests; minimize lock-screen content',serverRequired:true,channels:['on_call_push','manual_dialer','voice_provider','nurse_call_gateway'],request:{incident_id:'unique',encounter_id:'synthetic',priority:'clinician_confirmed',reason:'structured_context',requested_team:'physician_or_ICU',observed_at:'ISO8601',rule_version:'approved_version'},response_states:['queued','provider_accepted','delivery_confirmed','clinician_acknowledged','failed','timeout','closed'],requirements:['idempotency','role-based authorization','delivery receipts distinct from acknowledgment','server timer and backup escalation','audit retention','hardware acknowledgment','test environment validation']})}
function safetyFeedback(){const e=state.events;return{events:e.length,reopened:e.filter(x=>/undone|Reopened|unreviewed/i.test(x.action)).length,deferred:e.filter(x=>/deferred/i.test(x.action)).length,escalations:state.escalations.length,open:state.escalations.filter(x=>x.status!=='closed').length,overdue:state.escalations.filter(x=>escalationStatus(x).startsWith('Overdue')).length,currentGaps:allSafetyIssues().length}}
function showSafetyFeedback(){const f=safetyFeedback();openDialog('Audit reflection & feedback',`<p>Deterministic summary of local demo events and current record gaps; not a clinical outcome evaluation.</p><div class="stage">${f.reopened} reopen / undo events → review whether labels or workflow caused accidental completion.</div><div class="stage">${f.deferred} deferral events → inspect reasons before changing alert thresholds.</div><div class="stage">${f.open} open demo escalations, ${f.overdue} overdue → inspect responsibility and backup routing.</div><div class="stage">${f.currentGaps} current data-derived gaps → prioritize completeness and documentation reconciliation.</div><p>Counts are events, not unique patients or error rates. No causal improvement claim is made.</p><button class="btn" onclick="download('fn-safety-feedback.json',f)">Export feedback</button>`)}
const auditBeforeSafety=audit;audit=function(){const f=safetyFeedback();return header('Audit & learning','A local record of actions, reversals, escalations and opportunities to improve.',`<button class="btn primary" onclick="showSafetyFeedback()">Reflection & feedback</button>`)+`<div class="compactstats"><span><b>${f.events}</b> local events</span><span><b>${f.reopened}</b> reopen / undo events</span><span><b>${f.deferred}</b> deferral events</span><span><b>${f.escalations}</b> demo escalations</span></div><div class="notice">Browser-local logs are editable and device-specific. They are not an immutable, authenticated clinical audit service.</div>`+auditBeforeSafety().slice(auditBeforeSafety().indexOf('<section'))};
const detailBeforeSafety=detail;detail=function(){let h=detailBeforeSafety();if(selected)h=h.replace('<div class="assessmentactions">',`<div class="assessmentactions"><button class="btn" onclick="openEscalation('${id(selected)}')">Escalate / notify (demo)</button>`);return h};
const renderBeforeSafety=render;render=function(){renderBeforeSafety();if(view==='Escalation center')$('#app').innerHTML=escalationView()};
setInterval(()=>{if(view==='Escalation center'&&!document.querySelector('#workflowDialog'))render()},15000);

let knownSafetyKeys=null;
function toggleSafetyMonitor(){state.localSafetyMonitor=!state.localSafetyMonitor;knownSafetyKeys=new Set(allSafetyIssues().filter(i=>i.severity==='urgent').map(i=>i.key));save('Local foreground safety monitoring '+(state.localSafetyMonitor?'enabled':'disabled')+'; no remote dispatch')}
function monitorSafetyChanges(){if(!state.localSafetyMonitor)return;const urgent=allSafetyIssues().filter(i=>i.severity==='urgent'),keys=new Set(urgent.map(i=>i.key));if(!knownSafetyKeys){knownSafetyKeys=keys;return}const fresh=urgent.filter(i=>!knownSafetyKeys.has(i.key));knownSafetyKeys=keys;if(!fresh.length)return;state.events.unshift({time:new Date().toISOString(),patient:'Safety monitor',action:'New local urgent-review flags: '+fresh.length+'; clinician context required; no external dispatch'});try{localStorage.setItem('fn-demo-v1',JSON.stringify(state))}catch{}document.querySelector('#safetyToast')?.remove();const box=document.createElement('div');box.id='safetyToast';box.className='safetytoast';box.setAttribute('role','alert');box.innerHTML='<b>New safety concern · synthetic workspace</b><p>'+fresh.length+' new urgent-review flag(s). Confirm patient context and measurement freshness.</p><button class="btn" onclick="openSafetyToast()">Open safety queue</button> <button class="btn" onclick="dismissSafetyToast()">Dismiss notice</button>';document.body.append(box)}
const renderWithEscalation=render;render=function(){renderWithEscalation();monitorSafetyChanges()};

function dismissSafetyToast(){document.querySelector('#safetyToast')?.remove()}
function openSafetyToast(){dismissSafetyToast();go('Safety & process')}
